pm.test("R1 punya student_count 1 (S1); R3 (terhapus) tidak ada; struktur field lengkap", function () { const rs = j.data.rombels; const r1 = rs.find(function (x) { return x.id == pm.environment.get('r1_id'); });
  pm.expect(r1).to.be.an('object'); pm.expect(r1.student_count).to.eql(1);
  ['id','name','grade_level','student_count','average_submitted_today'].forEach(function (k) { pm.expect(r1).to.have.property(k); });
  pm.expect(rs.map(function (x) { return x.id; })).to.not.include(Number(pm.environment.get('r3_id'))); });
